                        dataKeys.push(dataKey);
                    } else if (dataKey.type === this.typesRef.dataKeyType.alarm) {
                        alarmDataKeys.push(dataKey);
                    }
                }
                this.dataKeys = dataKeys;
                this.alarmDataKeys = alarmDataKeys;
            }
        };
