  updateValidity(...rest: any[]): any {
    if (ngModelCtrl.$viewValue) {
        var value: any = ngModelCtrl.$viewValue;
        var dataValid: any = (value !== undefined) && value != null;
        ngModelCtrl.control?.setErrors(dataValid ? null : { entityData: true });
        if (dataValid) {
            ngModelCtrl.control?.setErrors(
                ((value.entityAliasId !== undefined) && value.entityAliasId != null) ? null : { entityAlias: true });
            if (this.optDataKeys()) {
                ngModelCtrl.control?.setErrors(null);
            } else {
                ngModelCtrl.control?.setErrors(
                    ((value.dataKeys !== undefined) &&
                    value.dataKeys != null &&
                    value.dataKeys.length > 0) ? null : { entityKeys: true });
            }
        }
    }
  }
